            tiles.append((r0, r1, c0, c1, color))

    if not tiles:
        return out

    counts = {}
    for tile in tiles:
        counts[tile[4]] = counts.get(tile[4], 0) + 1
    ordinary = max(counts, key=counts.get)

    # Group tiles by tile-row and tile-column.
    row_groups, col_groups = {}, {}
    for tile in tiles:
        r0, r1, c0, c1, color = tile
        row_groups.setdefault((r0, color), []).append(tile)
        col_groups.setdefault((c0, color), []).append(tile)

    # Connect non-ordinary matching markers. The connector has the same
    # thickness as the marked interior of a tile.
    for (row, color), group in row_groups.items():
        if color == ordinary or len(group) < 2:
            continue
        group.sort(key=lambda t: t[2])
        for left, right in zip(group, group[1:]):
            for y in range(left[0] + 1, left[1]):
                for x in range(left[3] + 1, right[2]):
                    if grid[y][x] == 0:
                        out[y][x] = color

    for (col, color), group in col_groups.items():
        if color == ordinary or len(group) < 2:
            continue
        group.sort(key=lambda t: t[0])
        for upper, lower in zip(group, group[1:]):
            for y in range(upper[1] + 1, lower[0]):
                for x in range(upper[2] + 1, upper[3]):
                    if grid[y][x] == 0:
                        out[y][x] = color

    return out
